```js
function debounce(fn, ms, { leading = false } = {}) {
  let timer = null;

  // function, no arrow: necesitamos el this del llamador.
  function debounced(...args) {
    const llamarAhora = leading && timer === null;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, ms);

    if (llamarAhora) fn.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// Uso
const buscar = debounce(function (q) { api.search(q); }, 300);
input.addEventListener('input', (e) => buscar(e.target.value));
// Al desmontar: buscar.cancel();
```

