```js
function crearBuscador(onResultado, onError, onEstado) {
  let timer = null;
  let controller = null;
  let generacion = 0;

  function buscar(q) {
    clearTimeout(timer);
    controller?.abort();          // cancela la anterior

    if (q.trim() === '') { onResultado([]); return; }

    timer = setTimeout(async () => {
      const miGeneracion = ++generacion;
      controller = new AbortController();
      onEstado('cargando');

      try {
        const r = await fetch(`/api/buscar?q=${encodeURIComponent(q)}`, {
          signal: controller.signal,
        });
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        const datos = await r.json();

        // La garantía: llegó tarde, ya hay una búsqueda más reciente.
        if (miGeneracion !== generacion) return;
        onResultado(datos);
        onEstado(datos.length ? 'ok' : 'vacio');
      } catch (e) {
        if (e.name === 'AbortError') return;   // esperado, no es un fallo
        if (miGeneracion !== generacion) return;
        onError(e);
        onEstado('error');
      }
    }, 300);
  }

  buscar.destruir = () => { clearTimeout(timer); controller?.abort(); };
  return buscar;
}
```

```js
function memoizeAsync(fn, { ttl = 60_000, max = 100 } = {}) {
  const cache = new Map();   // clave -> { promise, expira }

  function get(key) {
    const hit = cache.get(key);
    if (hit && hit.expira > Date.now()) {
      // Reinserción: el más reciente queda al final (LRU simple).
      cache.delete(key);
      cache.set(key, hit);
      return hit.promise;
    }

    // SÍNCRONO, antes de cualquier await: es lo que evita el stampede.
    const promise = fn(key);
    cache.set(key, { promise, expira: Date.now() + ttl });

    // Si falla, se retira para no envenenar la clave.
    promise.catch(() => {
      if (cache.get(key)?.promise === promise) cache.delete(key);
    });

    // Desalojo del más antiguo: Map conserva el orden de inserción.
    if (cache.size > max) cache.delete(cache.keys().next().value);

    return promise;
  }

  get.invalidate = (key) => cache.delete(key);
  get.clear = () => cache.clear();
  return get;
}
```

