const cache = new Map();

export function abrirPanel(datos) {
  const nodo = document.createElement('div');
  const controller = new AbortController();

  cache.set(datos.id, { datos, nodo });

  // La signal da de baja TODOS los listeners de una vez.
  window.addEventListener('resize', () => recolocar(nodo), {
    signal: controller.signal,
  });

  const t = setInterval(() => refrescar(datos), 1000);
  document.body.append(nodo);

  return function cerrar() {
    controller.abort();     // todos los listeners, de golpe
    clearInterval(t);       // el temporizador
    cache.delete(datos.id); // la entrada de la caché
    nodo.remove();          // y ahora sí es recolectable
  };
}
```

```js
async function mapConcurrente(items, tarea, { concurrencia = 6 } = {}) {
  const resultados = new Array(items.length);
  let siguiente = 0;

  async function trabajador() {
    while (true) {
      // Atómico: no hay await entre la lectura y el incremento.
      const i = siguiente++;
      if (i >= items.length) return;

      try {
        resultados[i] = { ok: true, valor: await tarea(items[i], i) };
      } catch (error) {
        // Un fallo no aborta el resto.
        resultados[i] = { ok: false, error };
      }
    }
  }

  await Promise.all(
    Array.from({ length: Math.min(concurrencia, items.length) }, trabajador),
  );

  return resultados;
}

// Uso
const r = await mapConcurrente(urls, (u) => fetch(u).then((x) => x.json()));
const fallidas = r.filter((x) => !x.ok).length;
```

```js
class EventEmitter {
  #listeners = new Map();   // evento -> Set<fn>

  on(evento, fn) {
    if (!this.#listeners.has(evento)) this.#listeners.set(evento, new Set());
    this.#listeners.get(evento).add(fn);
    return () => this.off(evento, fn);    // baja cómoda
  }

  once(evento, fn) {
    const wrapper = (...args) => {
      this.off(evento, wrapper);   // antes de invocar, por si lanza
      fn(...args);
    };
    return this.on(evento, wrapper);
  }

  off(evento, fn) {
    const set = this.#listeners.get(evento);
    if (!set) return;
    set.delete(fn);
    if (set.size === 0) this.#listeners.delete(evento);  // sin basura
  }

  emit(evento, ...args) {
    const set = this.#listeners.get(evento);
    if (!set) return false;

    // Copia: un listener puede darse de baja durante la emisión.
    for (const fn of [...set]) {
      try {
        fn(...args);
      } catch (error) {
        // Un suscriptor roto no debe tumbar a los demás.
        queueMicrotask(() => { throw error; });
      }
    }
    return true;
  }
}
```

```js
// --- Node
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';

async function procesar(ruta) {
  const rl = createInterface({
    input: createReadStream(ruta, { encoding: 'utf8' }),
    crlfDelay: Infinity,          // trata \r\n como un solo salto
  });

  let cumplen = 0, suma = 0, contados = 0, primera = true;

  // await for: contrapresión automática, memoria constante.
  for await (const linea of rl) {
    if (primera) { primera = false; continue; }
    if (!linea) continue;

    const campos = linea.split(',');
    const valor = Number(campos[2]);
    if (Number.isNaN(valor)) continue;   // fila corrupta: no abortar

    if (campos[1] === 'activo') cumplen++;
    suma += valor;
    contados++;
  }

  return { cumplen, media: contados ? suma / contados : 0 };
}

// --- Navegador
async function procesarRemoto(url) {
  const res = await fetch(url);
  const reader = res.body
    .pipeThrough(new TextDecoderStream())   // gestiona UTF-8 partido
    .getReader();

  let resto = '', contados = 0, suma = 0;

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;

    const lineas = (resto + value).split('\n');
    resto = lineas.pop();          // la última puede estar incompleta

    for (const l of lineas) {
      const v = Number(l.split(',')[2]);
      if (!Number.isNaN(v)) { suma += v; contados++; }
    }
  }
  return { media: contados ? suma / contados : 0 };
}
```

```js
// Cada operación lleva su clave de idempotencia desde el cliente.
async function encolar(tipo, payload, entidadId) {
  await db.put('outbox', {
    id: crypto.randomUUID(),      // clave de idempotencia
    entidadId,                    // para ordenar por entidad
    tipo,
    payload,
    intentos: 0,
    creadoEn: Date.now(),
    estado: 'pendiente',
  });
  aplicarLocalmente(tipo, payload);   // optimista: la UI no espera
  procesarCola();
}

async function procesarCola() {
  if (!navigator.onLine) return;

  const pendientes = await db.getAllFromIndex('outbox', 'creadoEn');

  for (const op of pendientes) {
    try {
      await api.aplicar(op, { headers: { 'Idempotency-Key': op.id } });
      await db.delete('outbox', op.id);
    } catch (e) {
      if (esPermanente(e)) {
        // 4xx de validación: reintentar no cambia nada.
        await db.put('outbox', { ...op, estado: 'fallida', error: `${e}` });
        notificarUsuario(op, e);
        continue;
      }
      // Transitorio: backoff exponencial CON jitter.
      const espera = Math.min(2 ** op.intentos * 1000, 60_000);
      const conJitter = Math.random() * espera;
      await db.put('outbox', { ...op, intentos: op.intentos + 1 });
      setTimeout(procesarCola, conJitter);
      return;   // preservar el orden: no saltar a la siguiente
    }
  }
}

const esPermanente = (e) => e.status >= 400 && e.status < 500 && e.status !== 401;

window.addEventListener('online', procesarCola);
```

