  // translateY, no top: se compone en GPU, sin layout.
  contenido.style.transform = `translateY(${inicio * ALTURA}px)`;
  contenido.replaceChildren(...items.slice(inicio, fin).map(fila));
}

viewport.addEventListener('scroll', () => {
  // rAF, no throttle: sincroniza con el repintado.
  requestAnimationFrame(() => render(viewport.scrollTop));
}, { passive: true });

// --- Altura variable: offsets acumulados + búsqueda binaria
const alturas = new Array(items.length).fill(ESTIMADA);
const offsets = new Float64Array(items.length + 1);

function recalcularDesde(i) {
  for (let k = i; k < alturas.length; k++) offsets[k + 1] = offsets[k] + alturas[k];
}

function indiceEn(y) {          // O(log n) en vez de O(n)
  let lo = 0, hi = alturas.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (offsets[mid] <= y) lo = mid; else hi = mid - 1;
  }
  return lo;
}

const ro = new ResizeObserver((entries) => {
  let minCambiado = Infinity;
  for (const e of entries) {
    const i = Number(e.target.dataset.index);
    const real = e.contentRect.height;
    if (Math.abs(alturas[i] - real) < 0.5) continue;
    // Si la fila corregida está por encima, compensar para no dar un salto.
    if (i < primeraVisible) viewport.scrollTop += real - alturas[i];
    alturas[i] = real;
    minCambiado = Math.min(minCambiado, i);
  }
  if (minCambiado !== Infinity) { recalcularDesde(minCambiado); render(viewport.scrollTop); }
});
